using System.Text.Json;
using System.Text.Json.Nodes;
using GenesisMesh;
using GenesisMesh.Tests;
using Xunit;

namespace GenesisMesh.Sdk.Tests;

/// <summary>
/// Shared conformance suite <c>vouching</c> (1.8.0), generated by the Python reference
/// (genesismesh/conformance/generate_vectors.py vouching) and copied here unchanged: records of a succeeded NA key
/// (attestations, treaties, revocation feeds and grants) judged at their own time and judged now. Every vector runs.
/// Then the horizon helpers, the grace hint and the grant check judged now.
/// </summary>
public class VouchingTests
{
    private static readonly string SuitePath = Path.Combine(AppContext.BaseDirectory, "testdata", "conformance", "vouching.json");
    private static readonly HashSet<string> KindsRun = new() { "record_vouching" };

    private static JsonElement.ArrayEnumerator Vectors()
    {
        var root = JsonDocument.Parse(File.ReadAllText(SuitePath)).RootElement;
        Assert.Equal("vouching", root.GetProperty("suite").GetString());
        return root.GetProperty("vectors").EnumerateArray();
    }

    private static JsonElement Vector(string id) => Vectors().Single(v => v.GetProperty("id").GetString() == id);

    public static IEnumerable<object[]> VectorIds() => Vectors().Select(v => new object[] { v.GetProperty("id").GetString()! });

    internal static ConformanceReceipt Receipt() => ConformanceReceipts.For(
        "vouching", typeof(VouchingTests), nameof(ReproducesTheReferenceVerdicts), VectorIds(), KindsRun);

    [Fact]
    public void EveryKindIsRunOrListedAsNotRun() => ConformanceReceipts.Record(Receipt());

    private static NAKeyHistory History(JsonElement input)
    {
        var result = OfflineVerifier.VerifyKeyHistory(input.GetProperty("genesis").GetRawText(),
            input.GetProperty("successions").GetRawText(), input.GetProperty("root_public_key").GetString()!);
        Assert.True(result.Verified, result.Reason);
        var history = result.History!;
        return input.TryGetProperty("grace_seconds", out var grace)
            ? history.WithVouchingGrace(TimeSpan.FromSeconds(grace.GetDouble()))
            : history;
    }

    private static string? Expected(JsonElement expected, string name) =>
        expected.GetProperty(name).ValueKind == JsonValueKind.Null ? null : expected.GetProperty(name).GetString();

    [Theory]
    [MemberData(nameof(VectorIds))]
    public void ReproducesTheReferenceVerdicts(string id)
    {
        var v = Vector(id);
        Assert.Equal("record_vouching", v.GetProperty("kind").GetString());
        var input = v.GetProperty("input");
        var model = v.GetProperty("model").GetString()!;
        var record = input.GetProperty("record").GetRawText();
        var history = History(input);
        var now = OfflineVerifier.ParseTimestamp(input.GetProperty("now").GetString()!);
        var expected = v.GetProperty("expected");
        Assert.Equal(Expected(expected, "at_record_time"), OfflineVerifier.NARecordRefusal(model, record, history));
        Assert.Equal(Expected(expected, "now"), OfflineVerifier.NARecordRefusal(model, record, history, now));
    }

    [Fact]
    public void TheHorizonIsTheEndTheHandOverAndTheGrace()
    {
        var succeeded = new DateTimeOffset(2026, 1, 11, 0, 0, 0, TimeSpan.Zero);
        var validTo = succeeded.AddDays(365);
        var history = new NAKeyHistory("TEST", null, new[]
        {
            new NAKey(1, "na-1", "old", null, succeeded, null, false),
            new NAKey(2, "na-2", "new", succeeded, null, validTo, true),
        });
        Assert.Equal(NAKeyHistory.SuccessionVouchingGrace, history.VouchingGrace);
        var shortGrace = history.WithVouchingGrace(TimeSpan.FromHours(1));
        var horizon = succeeded + NAKeyHistory.SuccessionHandover + TimeSpan.FromHours(1);
        Assert.Equal(horizon, shortGrace.VouchesUntil("old"));
        Assert.False(shortGrace.RecordOutlivesKey("old", horizon.AddTicks(-1)));
        Assert.True(shortGrace.RecordOutlivesKey("old", horizon));
        Assert.Equal(new[] { "old" }, shortGrace.KeysVouchingAt(succeeded.AddSeconds(-1), horizon.AddSeconds(-1)));
        Assert.Empty(shortGrace.KeysVouchingAt(succeeded.AddSeconds(-1), horizon));
        // The new key ends at its enforced valid_to; a key with no end, or outside the history, has no horizon.
        Assert.Equal(validTo + NAKeyHistory.SuccessionHandover + TimeSpan.FromHours(1), shortGrace.VouchesUntil("new"));
        Assert.Null(NAKeyHistory.ValidAlways(new[] { "k" }).VouchesUntil("k"));
        Assert.Null(shortGrace.VouchesUntil("stranger"));
        // The grace only shortens; the original is unchanged; a grace above 24 hours is refused.
        Assert.Equal(TimeSpan.FromHours(1), shortGrace.WithVouchingGrace(TimeSpan.FromHours(10)).VouchingGrace);
        Assert.Equal(NAKeyHistory.SuccessionVouchingGrace, history.VouchingGrace);
        Assert.Equal(TimeSpan.Zero, history.WithVouchingGrace(TimeSpan.FromSeconds(-1)).VouchingGrace);
        Assert.Throws<ArgumentOutOfRangeException>(() =>
            new NAKeyHistory("TEST", null, history.Keys, TimeSpan.FromHours(25)));
    }

    [Theory]
    [InlineData("600", 600)]
    [InlineData("864000", 86400)]
    [InlineData("\"600\"", 86400)]
    [InlineData(null, 86400)]
    public void TheNAsGraceHintOnlyShortensTheGrace(string? hint, double expectedSeconds)
    {
        var input = Vector("attestation-old-key-within-grace").GetProperty("input");
        var body = new JsonObject
        {
            ["genesis"] = JsonNode.Parse(input.GetProperty("genesis").GetRawText()),
            ["successions"] = JsonNode.Parse(input.GetProperty("successions").GetRawText()),
        };
        if (hint is not null) body["vouching_grace_seconds"] = JsonNode.Parse(hint);
        var result = OfflineVerifier.VerifyKeyHistoryResponse(body.ToJsonString(), input.GetProperty("root_public_key").GetString()!);
        Assert.True(result.Verified, result.Reason);
        Assert.Equal(TimeSpan.FromSeconds(expectedSeconds), result.History!.VouchingGrace);
    }

    [Fact]
    public void AGrantJudgedNowOutlivesItsKeyPastTheHorizon()
    {
        var inside = Vector("grant-old-key-within-grace").GetProperty("input");
        var past = Vector("grant-old-key-after-horizon").GetProperty("input");
        var history = History(inside);
        DateTimeOffset Now(JsonElement input) => OfflineVerifier.ParseTimestamp(input.GetProperty("now").GetString()!);
        Assert.Equal("accepted", OfflineVerifier.VerifyCapabilityGrant(inside.GetProperty("record").GetRawText(), history, Now(inside)).Reason);
        var refused = OfflineVerifier.VerifyCapabilityGrant(past.GetProperty("record").GetRawText(), history, Now(past));
        Assert.False(refused.Valid);
        Assert.Equal("outlives_key", refused.Reason);
        Assert.Equal("accepted", OfflineVerifier.VerifyCapabilityGrant(past.GetProperty("record").GetRawText(), history).Reason);
        var fresh = Vector("grant-new-key").GetProperty("input");
        Assert.Equal("accepted", OfflineVerifier.VerifyCapabilityGrant(fresh.GetProperty("record").GetRawText(), history, Now(fresh)).Reason);
    }
}
